  `item_name` varchar(255) NOT NULL,
  `quantity` int(11) NOT NULL DEFAULT 0,
  `dispensed` int(11) NOT NULL DEFAULT 0,
  `description` text NOT NULL,
  `supplier` varchar(255) DEFAULT NULL,
  `unit_price` decimal(10,2) DEFAULT NULL COMMENT 'Price per unit',
  `status` enum('active','archive') NOT NULL DEFAULT 'active',
  `delivery_date` date DEFAULT NULL COMMENT 'Date of delivery',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
