--
-- Triggers `inventory`
--
DELIMITER $$
CREATE TRIGGER `after_inventory_insert` AFTER INSERT ON `inventory` FOR EACH ROW BEGIN
  UPDATE batch_deliveries
  SET total_items = (
    SELECT COUNT(DISTINCT item_code) 
    FROM inventory 
    WHERE batch_number = NEW.batch_number
  )
  WHERE batch_number = NEW.batch_number;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_inventory_update` AFTER UPDATE ON `inventory` FOR EACH ROW BEGIN
    -- Check for low stock
    IF NEW.quantity <= 10 AND NEW.quantity <> OLD.quantity THEN
        VALUES ('low_stock', NEW.item_code, NEW.batch_number,
                CONCAT('Low stock alert: ', NEW.item_name, ' has only ', NEW.quantity, ' units remaining'),
                NOW());
    END IF;
    
    -- Check for expiring items (within 30 days)
    IF DATEDIFF(NEW.expiry_date, CURDATE()) <= 30 AND DATEDIFF(NEW.expiry_date, CURDATE()) > 0 THEN
        VALUES ('expiring_soon', NEW.item_code, NEW.batch_number,
                CONCAT('Expiring soon: ', NEW.item_name, ' expires on ', DATE_FORMAT(NEW.expiry_date, '%Y-%m-%d')),
                NOW());
    END IF;
    
    -- Check for expired items
    IF NEW.expiry_date < CURDATE() AND OLD.expiry_date >= CURDATE() THEN
        VALUES ('expired', NEW.item_code, NEW.batch_number,
                CONCAT('EXPIRED: ', NEW.item_name, ' expired on ', DATE_FORMAT(NEW.expiry_date, '%Y-%m-%d')),
                NOW());
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `backup_inventory_insert` AFTER INSERT ON `inventory` FOR EACH ROW BEGIN
        id, batchId, code, name, quantity, dispensed, expiry, 
        description, status, created_at, updated_at, supplier
    ) VALUES (
        NEW.id, NEW.batch_number, NEW.item_code, NEW.item_name, 
        NEW.quantity, NEW.dispensed, NEW.expiry_date, NEW.description, 
        CASE WHEN NEW.status = 'archive' THEN 'archive' ELSE 'active' END, 
        NEW.created_at, NEW.updated_at, NEW.supplier
    );
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `backup_inventory_update` AFTER UPDATE ON `inventory` FOR EACH ROW BEGIN
        id, batchId, code, name, quantity, dispensed, expiry, 
        description, status, created_at, updated_at, supplier
    ) VALUES (
        NEW.id, NEW.batch_number, NEW.item_code, NEW.item_name, 
        NEW.quantity, NEW.dispensed, NEW.expiry_date, NEW.description, 
        CASE WHEN NEW.status = 'archive' THEN 'archive' ELSE 'active' END, 
        NEW.created_at, NEW.updated_at, NEW.supplier
    )
    ON DUPLICATE KEY UPDATE
        batchId = NEW.batch_number,
        code = NEW.item_code,
        name = NEW.item_name,
        quantity = NEW.quantity,
        dispensed = NEW.dispensed,
        expiry = NEW.expiry_date,
        description = NEW.description,
        status = CASE WHEN NEW.status = 'archive' THEN 'archive' ELSE 'active' END,
        updated_at = NEW.updated_at,
        supplier = NEW.supplier;
END
$$
DELIMITER ;

