DELIMITER $$
CREATE TRIGGER `after_medicine_dispensed` AFTER INSERT ON `medicine_dispensed` FOR EACH ROW BEGIN
    DECLARE remaining_qty INT;
    DECLARE med_name VARCHAR(255);
    
    -- Get remaining quantity and medicine name
    SELECT quantity, item_name INTO remaining_qty, med_name
    FROM inventory 
    WHERE id = NEW.inventory_id;
    
    -- Check if stock is low (10 or below)
    IF remaining_qty <= 10 THEN
        SELECT 'low_stock', item_code, batch_number, 
               CONCAT('Low stock alert: ', item_name, ' has only ', quantity, ' units remaining'),
               NOW()
        FROM inventory 
        WHERE id = NEW.inventory_id;
    END IF;
END
$$
